class Solution {
public:
    string minimumString(string a, string b, string c) {
        auto merge = [](const string& s1, const string& s2) {
            if (s1.find(s2) != string::npos) return s1;
            int max_overlap = min(s1.length(), s2.length());
            for (int i = max_overlap; i > 0; --i) {
                if (s1.compare(s1.length() - i, i, s2, 0, i) == 0) {
                    return s1 + s2.substr(i);
                }
            }
            return s1 + s2;
        };
        vector<string> candidates = {
            merge(merge(a, b), c),
            merge(merge(a, c), b),
            merge(merge(b, a), c),
            merge(merge(b, c), a),
            merge(merge(c, a), b),
            merge(merge(c, b), a)
        };
        string best = candidates[0];
        for (size_t i = 1; i < candidates.size(); ++i) {
            if (candidates[i].length() < best.length() || 
               (candidates[i].length() == best.length() && candidates[i] < best)) {
                best = candidates[i];
            }
        }
        return best;
    }
};

class Solution {
    public String minimumString(String a, String b, String c) {
        String[] candidates = new String[]{
            merge(merge(a, b), c),
            merge(merge(a, c), b),
            merge(merge(b, a), c),
            merge(merge(b, c), a),
            merge(merge(c, a), b),
            merge(merge(c, b), a)
        };
        String best = candidates[0];
        for (int i = 1; i < candidates.length; i++) {
            if (candidates[i].length() < best.length() || 
               (candidates[i].length() == best.length() && candidates[i].compareTo(best) < 0)) {
                best = candidates[i];
            }
        }
        return best;
    }

    private String merge(String s1, String s2) {
        if (s1.contains(s2)) return s1;
        int maxOverlap = Math.min(s1.length(), s2.length());
        for (int i = maxOverlap; i > 0; i--) {
            if (s1.endsWith(s2.substring(0, i))) {
                return s1 + s2.substring(i);
            }
        }
        return s1 + s2;
    }
}

/**
 * @param {string} a
 * @param {string} b
 * @param {string} c
 * @return {string}
 */
var minimumString = function(a, b, c) {
    function merge(s1, s2) {
        if (s1.includes(s2)) return s1;
        const maxOverlap = Math.min(s1.length, s2.length);
        for (let i = maxOverlap; i > 0; i--) {
            if (s1.endsWith(s2.slice(0, i))) {
                return s1 + s2.slice(i);
            }
        }
        return s1 + s2;
    }
    const candidates = [
        merge(merge(a, b), c),
        merge(merge(a, c), b),
        merge(merge(b, a), c),
        merge(merge(b, c), a),
        merge(merge(c, a), b),
        merge(merge(c, b), a)
    ];
    let best = candidates[0];
    for (let i = 1; i < candidates.length; i++) {
        if (candidates[i].length < best.length || 
           (candidates[i].length === best.length && candidates[i] < best)) {
            best = candidates[i];
        }
    }
    return best;
};
